begin;
create function pg_temp.check_save(ok boolean,msg text) returns void language plpgsql as $$begin if not coalesce(ok,false) then raise exception '%',msg;end if;raise notice 'PASS: %',msg;end$$;
create function pg_temp.expect_save(stmt text,code text,msg text) returns void language plpgsql as $$begin begin execute stmt;exception when others then if sqlstate=code then raise notice 'PASS: %',msg;return;else raise;end if;end;raise exception 'Expected failure: %',msg;end$$;
insert into auth.users(id,email_confirmed_at) values('60030000-0000-4000-8000-000000000001',now());
insert into public.properties values('hu60-save-p','60030000-0000-4000-8000-000000000001','{}','2026-10-11T00:00:00Z');
select pg_temp.check_save(not has_function_privilege('authenticated','public.save_computed_scenario(uuid,text,timestamptz,timestamptz,text,uuid,jsonb)','execute') and not has_function_privilege('anon','public.save_computed_scenario(uuid,text,timestamptz,timestamptz,text,uuid,jsonb)','execute'),'only server may submit computed snapshots');
set local role service_role;
select public.save_computed_scenario('60030000-0000-4000-8000-000000000001','hu60-save-p','2026-10-11T00:00:00Z',null,'First','60030000-0000-4000-8000-000000000010','{"property":{"id":"hu60-save-p"},"engine":"test","result":{"profit":100}}');
select pg_temp.check_save((public.save_computed_scenario('60030000-0000-4000-8000-000000000001','hu60-save-p','2026-10-11T00:00:00Z',null,'First','60030000-0000-4000-8000-000000000010')->>'replayed')::boolean,'receipt lookup without recalculation');
select pg_temp.expect_save($q$select public.save_computed_scenario('60030000-0000-4000-8000-000000000001','hu60-save-p','2026-10-11T00:00:00Z',null,'Changed','60030000-0000-4000-8000-000000000010')$q$,'40001','changed request denied');
select pg_temp.expect_save($q$select public.save_computed_scenario('60030000-0000-4000-8000-000000000001','hu60-save-p','2026-10-10T00:00:00Z',null,'Stale','60030000-0000-4000-8000-000000000011','{"property":{"id":"hu60-save-p"},"engine":"test","result":{}}')$q$,'40001','stale version denied');
select pg_temp.expect_save($q$select public.save_computed_scenario('60030000-0000-4000-8000-000000000001','hu60-save-p','2026-10-11T00:00:00Z','2026-10-11T00:00:00Z','Book','60030000-0000-4000-8000-000000000012','{"property":{"id":"hu60-save-p"},"engine":"test","result":{}}')$q$,'40001','book version denied');
select pg_temp.expect_save($q$select public.save_computed_scenario('60030000-0000-4000-8000-000000000099','hu60-save-p','2026-10-11T00:00:00Z',null,'Actor','60030000-0000-4000-8000-000000000013','{"property":{"id":"hu60-save-p"},"engine":"test","result":{}}')$q$,'42501','unknown actor denied');
reset role;
select pg_temp.check_save((select count(*)=1 from public.analysis_scenarios where property_id='hu60-save-p') and (select count(*)=1 from public.audit_events where property_id='hu60-save-p'),'scenario and audit committed once');
create function pg_temp.fail_save_audit() returns trigger language plpgsql as $$begin if new.property_id='hu60-save-p' then raise exception using errcode='P0001',message='Synthetic failure';end if;return new;end$$;
create trigger hu60_test_save_failure before insert on public.audit_events for each row execute function pg_temp.fail_save_audit();
set local role service_role;
select pg_temp.expect_save($q$select public.save_computed_scenario('60030000-0000-4000-8000-000000000001','hu60-save-p','2026-10-11T00:00:00Z',null,'Rollback','60030000-0000-4000-8000-000000000014','{"property":{"id":"hu60-save-p"},"engine":"test","result":{}}')$q$,'P0001','audit failure propagates');
reset role;
select pg_temp.check_save((select count(*)=1 from public.analysis_scenarios where property_id='hu60-save-p'),'failed audit rolls back scenario');
select pg_temp.check_save(not has_table_privilege('service_role','public.analysis_scenarios','insert'),'server has no direct insert grant');
rollback;
